    image: "/poi-images/danangombe-history-v2.webp",
    description: {
      de: "Ehemals Dhlo-Dhlo genannt, war es ein wichtiges Zentrum des Rozvi-Reiches.",
      hu: "A korábban Dhlo-Dhlo néven ismert hely a Rozvi Birodalom fontos központja volt.",
      ro: "Cunoscut anterior ca Dhlo-Dhlo, a fost un centru important al Imperiului Rozvi.",
      en: "Formerly known as Dhlo-Dhlo, it was an important center of the Rozvi Empire.",
      es: "Antiguamente llamada Dhlo-Dhlo, fue un centro importante del Imperio Rozvi.",
      pt: "Anteriormente chamada Dhlo-Dhlo, era um centro importante do Império Rozvi.",
      fr: "Anciennement appelée Dhlo-Dhlo, c'était un centre important de l'Empire Rozvi.",
    },
    facts: {
      de: [
        "Gegründet im späten 17. Jahrhundert.",
        "Fundort spanischer Silbermünzen und portugiesischer Artefakte."
      ],
      hu: [
        "A 17. század végén alapították.",
        "Spanyol ezüstpénzeket és portugál leleteket találtak itt."
      ],
      ro: [
        "Fondat la sfârșitul secolului al XVII-lea.",
        "Locul descoperirii monedelor de argint spaniole și artefactelor portugheze."
      ],
      en: [
        "Founded in the late 17th century.",
        "Site where Spanish silver coins and Portuguese artifacts were found."
      ],
      es: ["Fundada a finales del siglo XVII.", "Lugar de hallazgo de monedas de plata españolas y artefactos portugueses."],
      pt: ["Fundada no final do século XVII.", "Local de descoberta de moedas de prata espanholas e artefactos portugueses."],
      fr: ["Fondée à la fin du XVIIe siècle.", "Lieu de découverte de pièces d'argent espagnoles et d'artefacts portugais."],
    },
    descriptionAdvanced: {
      de: "Danangombe, früher bekannt als Dhlo-Dhlo, war eine bedeutende Stadt und Hauptstadt des Rozvi-Reiches im späten 17. und 18. Jahrhundert. Die Ruinen liegen im Zentrum Simbabwes und weisen eine Architektur auf, die stark von der Khami-Kultur beeinflusst ist, jedoch eigene stilistische Merkmale entwickelte. Die massiven Steinmauern sind mit aufwendigen Mustern wie Schachbrett- und Stufenmotiven verziert, was den hohen sozialen Status der Bewohner unterstreicht. Als administratives und rituelles Zentrum war Danangombe ein Ort großer politischer Macht, von dem aus der Mambo (König) weite Teile des Plateaus kontrollierte. Archäologische Grabungen förderten Schätze wie Kanonen, Glasperlen und chinesisches Porzellan zu Tage, die den Wohlstand durch den Goldhandel belegen. Die Stadt wurde schließlich in den 1830er Jahren während der Mfecane-Unruhen verlassen. Heute bietet Danangombe einen tiefen Einblick in die Spätphase der simbabwischen Steinbau-Tradition vor der Kolonialisierung.",
      hu: "Danangombe, korábbi nevén Dhlo-Dhlo, a Rozvi Birodalom jelentős városa és fővárosa volt a 17. század végén és a 18. században. A romok Zimbabwe középső részén találhatók, építészetükön pedig erősen érezhető a Khami-kultúra hatása, bár saját stílusjegyeket is kifejlesztettek. A masszív kőfalakat bonyolult minták, például sakktábla- és lépcsőmotívumok díszítik, ami a lakók magas társadalmi státuszát hangsúlyozza. Adminisztratív és rituális központként Danangombe nagy politikai hatalommal bíró hely volt, ahonnan a Mambo (király) a fennsík jelentős részét ellenőrizte. A régészeti ásatások olyan kincseket tártak fel, mint ágyúk, üveggyöngyök és kínai porcelán, amelyek az aranykereskedelemből származó jólétet bizonyítják. A várost végül az 1830-as években, az Mfecane zavargások idején hagyták el. Ma Danangombe mély betekintést nyújt a gyarmatosítás előtti zimbabwei kőépítési hagyomány késői szakaszába.",
      ro: "Danangombe, cunoscut anterior sub numele de Dhlo-Dhlo, a fost un oraș important și capitala Imperiului Rozvi la sfârșitul secolului al XVII-lea și în secolul al XVIII-lea. Ruinele sunt situate în centrul Zimbabwe și prezintă o arhitectură influențată puternic de cultura Khami, dar cu trăsături stilistice proprii. Zidurile masive de piatră sunt decorate cu modele elaborate, precum șahul și motivele în trepte, subliniind statutul social înalt al locuitorilor. Ca centru administrativ și ritualic, Danangombe a fost un loc de mare putere politică, de unde Mambo (regele) controla zone extinse ale platoului. Săpăturile arheologice au scos la iveală comori precum tunuri, mărgele de sticlă și porțelan chinezesc, confirmând prosperitatea obținută din comerțul cu aur. Orașul a fost abandonat în cele din urmă în anii 1830, în timpul perioadei de instabilitate Mfecane. Astăzi, Danangombe oferă o perspectivă profundă asupra fazei târzii a tradiției construcțiilor din piatră din Zimbabwe.",
      en: "Danangombe, formerly known as Dhlo-Dhlo, was a significant city and the capital of the Rozvi Empire during the late 17th and 18th centuries. The ruins are situated in central Zimbabwe and exhibit an architecture heavily influenced by the Khami culture, though they developed distinct stylistic features. The massive stone walls are adorned with intricate patterns such as checkered and tiered motifs, underscoring the high social status of the residents. As an administrative and ritual center, Danangombe was a site of great political power, from which the Mambo (king) controlled vast areas of the plateau. Archaeological excavations have unearthed treasures including cannons, glass beads, and Chinese porcelain, testifying to the wealth derived from the gold trade. The city was ultimately abandoned in the 1830s during the Mfecane upheavals. Today, Danangombe provides a deep insight into the late stage of the Zimbabwean stone-building tradition prior to colonization.",
    },
    factsAdvanced: {
      de: ["Befindet sich im Insiza-Distrikt von Matabeleland South.", "Zwei gefundene Bronzekanonen deuten auf Kontakte zu Portugiesen hin.", "Verfügt über eindrucksvolle gestufte Plattformen für Elite-Häuser.", "Nach der Invasion der Nguni-Völker im 19. Jhdt. verlassen.", "Gilt als direkter Nachfolger der politischen Macht von Khami.", "Das Mauerwerk besteht aus lokalem Granit ohne Mörtel."],
      hu: ["Matabeleland South tartomány Insiza körzetében található.", "Két bronzágyút találtak itt, ami portugál kapcsolatokra utal.", "Lenyűgöző lépcsőzetes platformokkal rendelkezik az elit házai számára.", "A nguni népek 19. századi inváziója után hagyták el.", "Khami politikai hatalmának közvetlen utódjának tekintik.", "A falazat helyi gránitblokkokból készült, habarcs nélkül."],
      ro: ["Situat în districtul Insiza din Matabeleland South.", "Două tunuri de bronz găsite sugerează contacte cu portughezii.", "Dispune de platforme în trepte pentru locuințele elitelor.", "Abandonat în urma invaziei popoarelor Nguni în secolul XIX.", "Considerat un succesor direct al puterii politice de la Khami.", "Zidăria folosește blocuri de granit local fără mortar."],
      en: ["Located in the Insiza District of Matabeleland South.", "Two bronze cannons found here suggest contact with Portuguese traders.", "The site features impressive tiered platforms for elite housing.", "Abandoned following the invasion by the Nguni people in the 19th century.", "It is considered a direct successor to the political power of Khami.", "The stonework uses locally available granite blocks without mortar."],
      es: [],
      pt: [],
      fr: [],
    },
