      es: ["Están formadas por bloques de granito apilados artísticamente.", "Los hallazgos de cuentas de vidrio importadas demuestran amplias redes comerciales."],
      pt: ["Consistem em blocos de granito artisticamente empilhados.", "Achados de contas de vidro importadas comprovam amplas redes comerciais."],
