      ro: [
        "Construit în 1954 pentru a comemora traseul pionierilor.",
        "Trecătoarea a fost intens frecventată în secolul al XIX-lea."
      ],
      en: [
        "Erected in 1954 to commemorate the pioneer trail.",
        "The pass was heavily used in the 19th century."
      ],
      es: ["Erigido en 1954 en memoria de la ruta de los pioneros.", "El paso fue muy frecuentado en el siglo XIX."],
      pt: ["Erguido em 1954 em memória da trilha pioneira.", "O desfiladeiro foi muito frequentado no século XIX."],
